<?php
declare(strict_types=1);
require dirname(__DIR__) . '/app/bootstrap.php';
$user=requireLogin();require_once BASE_PATH.'/includes/rental-operations-common.php';ro_require_permission('invoices.manage');$pdo=Database::connection();$id=(int)($_GET['id']??$_POST['invoice_id']??0);
if(is_post()){
 ro_post_guard();try{$action=(string)($_POST['action']??'');
  if($action==='issue'){$dueDate=trim((string)($_POST['due_date']??''));if($dueDate!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$dueDate))throw new RuntimeException('Enter a valid invoice due date.');$stmt=$pdo->prepare("UPDATE invoices SET status='issued', issue_date=CURDATE(), due_date=? WHERE invoice_id=? AND status='draft'");$stmt->execute([$dueDate?:null,$id]);if(!$stmt->rowCount())throw new RuntimeException('Only a draft invoice can be issued.');RentalOperations::refreshInvoiceStatus($pdo,$id);RentalOperations::logEvent($pdo,isset($user['user_id'])?(int)$user['user_id']:null,'invoice.issued','invoice',(string)$id,'Invoice issued to customer', ['status'=>'draft'], ['status'=>'issued','due_date'=>$dueDate?:null]);ro_flash('success','Invoice issued. You can now record payments.');}
  elseif($action==='add_item'){$stmt=$pdo->prepare('SELECT status,discount_amount,tax_amount FROM invoices WHERE invoice_id=?');$stmt->execute([$id]);$inv=$stmt->fetch(PDO::FETCH_ASSOC);if(!$inv)throw new RuntimeException('Invoice not found.');if($inv['status']!=='draft')throw new RuntimeException('Itemized charges can only be changed while an invoice is a draft.');$type=(string)($_POST['item_type']??'other');$allowed=['rental','driver','extra_mileage','late_return','damage','cleaning','fuel','delivery','other'];if(!in_array($type,$allowed,true))throw new RuntimeException('Invalid line item type.');$desc=trim((string)($_POST['description']??''));$qty=(float)($_POST['quantity']??0);$unit=(float)($_POST['unit_price']??-1);if($desc===''||$qty<=0||$unit<0)throw new RuntimeException('Description, positive quantity and non-negative unit price are required.');$pdo->beginTransaction();$line=round($qty*$unit,2);$pdo->prepare('INSERT INTO invoice_items (invoice_id,item_type,description,quantity,unit_price,line_total) VALUES (?,?,?,?,?,?)')->execute([$id,$type,$desc,$qty,$unit,$line]);$stmt=$pdo->prepare("SELECT COALESCE(SUM(line_total),0) FROM invoice_items WHERE invoice_id=? AND item_type NOT IN ('discount','tax')");$stmt->execute([$id]);$subtotal=(float)$stmt->fetchColumn();$discount=(float)$inv['discount_amount'];$tax=(float)$inv['tax_amount'];$pdo->prepare('UPDATE invoices SET subtotal=?,total_amount=? WHERE invoice_id=?')->execute([$subtotal,max(0,$subtotal-$discount+$tax),$id]);$pdo->commit();RentalOperations::logEvent($pdo,isset($user['user_id'])?(int)$user['user_id']:null,'invoice.item_added','invoice',(string)$id,'Itemized charge added to draft invoice',null,['item_type'=>$type,'description'=>$desc,'quantity'=>$qty,'unit_price'=>$unit,'line_total'=>$line,'subtotal'=>$subtotal,'total_amount'=>max(0,$subtotal-$discount+$tax)]);ro_flash('success','Item added and invoice total recalculated.');}
  else throw new RuntimeException('Unknown invoice action.');
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();ro_flash('danger',$e->getMessage());}redirect('admin/invoice-view.php?id='.$id);
}
$stmt=$pdo->prepare('SELECT i.*,c.first_name,c.last_name,c.phone,c.email,c.address_line,c.city,c.country,r.rental_number,r.status AS rental_status,rs.reservation_code,v.make,v.model,v.registration_no FROM invoices i JOIN customers c ON c.customer_id=i.customer_id LEFT JOIN rentals r ON r.rental_id=i.rental_id LEFT JOIN reservations rs ON rs.reservation_id=i.reservation_id LEFT JOIN vehicles v ON v.vehicle_id=r.vehicle_id WHERE i.invoice_id=?');$stmt->execute([$id]);$i=$stmt->fetch(PDO::FETCH_ASSOC);if(!$i){http_response_code(404);exit('Invoice not found.');}
$balance=RentalOperations::invoiceBalance($pdo,$id);$itemsStmt=$pdo->prepare('SELECT * FROM invoice_items WHERE invoice_id=? ORDER BY invoice_item_id');$itemsStmt->execute([$id]);$items=$itemsStmt->fetchAll(PDO::FETCH_ASSOC);
$paymentsStmt=$pdo->prepare('SELECT p.*,COALESCE((SELECT SUM(pr.amount) FROM payment_refunds pr WHERE pr.payment_id=p.payment_id AND pr.status=\'processed\'),0) AS refunded FROM payments p WHERE p.invoice_id=? ORDER BY p.payment_date DESC');$paymentsStmt->execute([$id]);$payments=$paymentsStmt->fetchAll(PDO::FETCH_ASSOC);
$pageTitle='Invoice '.$i['invoice_number'];$currentPage='invoices';require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/rental-operations-nav.php';
?>
<div class="ro-shell"><div class="ro-page-heading no-print"><div><a class="ro-back-link" href="<?= e(base_url('admin/invoices.php')) ?>"><i class="bi bi-arrow-left"></i> Invoice register</a><h1><?= e($i['invoice_number']) ?></h1><p><?= e(trim($i['first_name'].' '.$i['last_name'])) ?> · <?= e($i['rental_number']?:'No rental linked') ?></p></div><div class="d-flex flex-wrap gap-2 align-items-center"><?= ro_status_badge($i['status']) ?><button type="button" onclick="window.print()" class="btn ro-btn-outline"><i class="bi bi-printer me-1"></i> Print invoice</button></div></div>
<div class="ro-invoice-document"><div class="ro-invoice-head"><div><div class="ro-brand-mark"><i class="bi bi-car-front-fill"></i></div><span class="ro-kicker">INVOICE</span><h2><?= e((string)setting('business_name','Car Rental Business')) ?></h2><p><?= e((string)setting('business_country','Rwanda')) ?> · Currency <?= e($i['currency']) ?></p></div><div class="ro-invoice-number"><span>INVOICE NUMBER</span><strong><?= e($i['invoice_number']) ?></strong><small>Issue date: <?= e(ro_date($i['issue_date'])) ?></small><small>Due date: <?= e(ro_date($i['due_date'])) ?></small><?= ro_status_badge($i['status']) ?></div></div>
<div class="ro-invoice-billto"><div><span class="ro-kicker">BILL TO</span><strong><?= e($i['first_name'].' '.$i['last_name']) ?></strong><p><?= e($i['phone']) ?><br><?= e($i['email']?:'') ?><br><?= e(trim(($i['address_line']??'').' '.($i['city']??'').' '.($i['country']??''))) ?></p></div><div><span class="ro-kicker">RENTAL REFERENCE</span><strong><?= e($i['rental_number']?:'—') ?></strong><p><?= e($i['reservation_code']?:'—') ?><br><?= e(($i['make']??'').' '.($i['model']??'')) ?><br><?= e($i['registration_no']??'') ?></p></div></div>
<div class="table-responsive"><table class="table ro-table ro-invoice-table"><thead><tr><th>Item</th><th>Description</th><th class="text-end">Quantity</th><th class="text-end">Unit price</th><th class="text-end">Line total</th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><span class="ro-type-pill"><?= e(ucwords(str_replace('_',' ',$item['item_type']))) ?></span></td><td><?= e($item['description']) ?></td><td class="text-end"><?= number_format((float)$item['quantity'],2) ?></td><td class="text-end"><?= ro_money($item['unit_price'],$i['currency']) ?></td><td class="text-end"><strong><?= $item['item_type']==='discount'?'− '.ro_money($item['unit_price'],$i['currency']):ro_money($item['line_total'],$i['currency']) ?></strong></td></tr><?php endforeach; ?></tbody></table></div>
<div class="ro-invoice-bottom"><div class="ro-invoice-notes"><span class="ro-kicker">NOTES</span><p><?= nl2br(e($i['notes']?:'Thank you for choosing our rental service. Please retain this invoice for your records.')) ?></p></div><div class="ro-totals"><div><span>Subtotal</span><strong><?= ro_money($i['subtotal'],$i['currency']) ?></strong></div><div><span>Discount</span><strong>− <?= ro_money($i['discount_amount'],$i['currency']) ?></strong></div><div><span>Tax</span><strong><?= ro_money($i['tax_amount'],$i['currency']) ?></strong></div><div class="total-line"><span>Total</span><strong><?= ro_money($i['total_amount'],$i['currency']) ?></strong></div><div><span>Payments received</span><strong><?= ro_money($balance['gross_paid'],$i['currency']) ?></strong></div><div><span>Processed refunds</span><strong>− <?= ro_money($balance['refunded'],$i['currency']) ?></strong></div><div class="balance-line"><span>Outstanding balance</span><strong><?= ro_money($balance['balance'],$i['currency']) ?></strong></div></div></div><div class="ro-document-note">A payment is counted only when recorded as completed. Refunds reduce the net amount paid only after they are processed. This invoice record does not itself process money through a bank or payment gateway.</div></div>
<div class="ro-panel mt-4 no-print"><div class="ro-panel-head"><div><span class="ro-kicker">INVOICE WORKFLOW</span><h2>Manage this invoice</h2></div></div><div class="ro-workflow-actions"><?php if($i['status']==='draft'): ?><form method="post" class="ro-inline-issue-form"><?= csrf_field() ?><input type="hidden" name="invoice_id" value="<?= $id ?>"><input type="hidden" name="action" value="issue"><label for="due_date" class="small text-secondary">Payment due date (optional)</label><input class="form-control form-control-sm" type="date" name="due_date" id="due_date" value="<?= e($i['due_date']??'') ?>"><button class="btn ro-btn-primary" type="submit"><i class="bi bi-send me-1"></i> Issue invoice</button></form><?php elseif(!in_array($i['status'],['void','paid','refunded'],true)): ?><a class="btn ro-btn-primary" href="<?= e(base_url('admin/payment-form.php?invoice_id='.$id)) ?>"><i class="bi bi-credit-card me-1"></i> Record payment</a><?php endif; ?><a class="btn ro-btn-outline" href="<?= e(base_url('admin/payments.php?invoice_id='.$id)) ?>">Payment register</a><a class="btn ro-btn-outline" href="<?= e(base_url('admin/refunds.php?invoice_id='.$id)) ?>">Refunds</a></div></div>
<?php if($i['status']==='draft'): ?><section class="ro-panel mt-4 no-print"><div class="ro-panel-head"><div><span class="ro-kicker">ITEMIZED BILLING</span><h2>Add agreed line item</h2><p>Draft invoices can be adjusted before issue. After issuing, create a separate adjustment invoice rather than rewriting a billed record.</p></div></div><form method="post" class="ro-form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="add_item"><input type="hidden" name="invoice_id" value="<?= $id ?>"><div class="ro-field"><label for="item_type">Charge type</label><select class="form-select" id="item_type" name="item_type"><?php foreach(['rental'=>'Rental','driver'=>'Driver','extra_mileage'=>'Extra mileage','late_return'=>'Late return','damage'=>'Damage','cleaning'=>'Cleaning','fuel'=>'Fuel','delivery'=>'Delivery','other'=>'Other'] as $v=>$label): ?><option value="<?= e($v) ?>"><?= e($label) ?></option><?php endforeach; ?></select></div><div class="ro-field ro-field-wide"><label for="description">Description</label><input class="form-control" id="description" name="description" maxlength="255" required></div><div class="ro-field"><label for="quantity">Quantity</label><input class="form-control" id="quantity" name="quantity" type="number" min="0.01" step="0.01" value="1" required></div><div class="ro-field"><label for="unit_price">Unit price (<?= e($i['currency']) ?>)</label><input class="form-control" id="unit_price" name="unit_price" type="number" min="0" step="0.01" required></div><div class="ro-form-actions"><button class="btn ro-btn-primary" type="submit"><i class="bi bi-plus-lg me-1"></i> Add item and recalculate</button></div></form></section><?php endif; ?>
<section class="ro-panel mt-4 no-print"><div class="ro-panel-head"><div><span class="ro-kicker">PAYMENT HISTORY</span><h2>Recorded transactions</h2></div><span class="ro-counter"><?= count($payments) ?> payments</span></div><?php if(!$payments): ?><div class="ro-empty compact"><div class="ro-empty-icon"><i class="bi bi-credit-card"></i></div><strong>No payments recorded</strong><p>Issue the invoice before recording money received.</p></div><?php else: ?><div class="table-responsive"><table class="table ro-table align-middle"><thead><tr><th>Receipt</th><th>Date</th><th>Method</th><th>Reference</th><th>Amount</th><th>Refunded</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($payments as $p): ?><tr><td><strong><?= e($p['payment_number']) ?></strong></td><td><?= e(ro_date($p['payment_date'])) ?></td><td><?= e(ucwords(str_replace('_',' ',$p['payment_method']))) ?></td><td><?= e($p['transaction_reference']?:'—') ?></td><td><?= ro_money($p['amount'],$i['currency']) ?></td><td><?= ro_money($p['refunded'],$i['currency']) ?></td><td><?= ro_status_badge($p['status']) ?></td><td><a class="btn btn-sm ro-btn-outline" href="<?= e(base_url('admin/payment-receipt.php?id='.(int)$p['payment_id'])) ?>">Receipt</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></div>
